setup:
MUTATE {
  CREATE CONCEPT ?alice { TYPE "Person" NAME "Alice" }
  CREATE CONCEPT ?bob { TYPE "Person" NAME "Bob" }
  CREATE CONCEPT ?carol { TYPE "Person" NAME "Carol" }
  CREATE CONCEPT ?quiet { TYPE "Option" NAME "Quiet" }
  CREATE CONCEPT ?loud { TYPE "Option" NAME "Loud" }
  ENSURE PROPOSITION ?unspoken (?alice, "prefers", ?quiet)
  ENSURE PROPOSITION ?repeated (?alice, "prefers", ?loud)
}

MUTATE {
  CREATE CONCEPT ?svc { TYPE "Service" NAME "api" }
  CREATE CONCEPT ?healthy { TYPE "Status" NAME "healthy" }
  CREATE CONCEPT ?degraded { TYPE "Status" NAME "degraded" }
  ENSURE PROPOSITION ?ok (?svc, "status", ?healthy)
  ENSURE PROPOSITION ?bad (?svc, "status", ?degraded)
}

MUTATE {
  CREATE CONCEPT ?dave { TYPE "Person" NAME "Dave" }
  CREATE CONCEPT ?warm { TYPE "Option" NAME "Warm" }
  ENSURE PROPOSITION ?p (?dave, "prefers", ?warm)
  CREATE EVIDENCE ?seen { SET FIELDS { evidence_class: "observation", payload: "one observation" } }
  CREATE ASSERTION ?a1 {
    SET FIELDS { proposition: ?p, asserted_by: ?dave, stance: "support", mode: "stated", confidence: 0.6 }
    SET STRUCTURAL { ("evidence", ?seen) { role: "support" } }
  }
  CREATE ASSERTION ?a2 {
    SET FIELDS { proposition: ?p, asserted_by: ?dave, stance: "support", mode: "stated", confidence: 0.6 }
    SET STRUCTURAL { ("evidence", ?seen) { role: "support" } }
  }
}

cases.command:
FIND(?b.status) WHERE {
  ?s CONCEPT {name: "Alice"}
  ?o CONCEPT {name: "Quiet"}
  ?p PROPOSITION (?s, "prefers", ?o)
  ?b BELIEF (?p)
}

FIND(?b.support.score, ?b.opposition.score) WHERE {
  ?s CONCEPT {name: "Alice"}
  ?o CONCEPT {name: "Quiet"}
  ?p PROPOSITION (?s, "prefers", ?o)
  ?b BELIEF (?p)
}

FIND(?b.support.score_semantics) WHERE {
  ?s CONCEPT {name: "Alice"}
  ?o CONCEPT {name: "Quiet"}
  ?p PROPOSITION (?s, "prefers", ?o)
  ?b BELIEF (?p)
}

FIND(?b.policy.id) WHERE {
  ?s CONCEPT {name: "Alice"}
  ?o CONCEPT {name: "Quiet"}
  ?p PROPOSITION (?s, "prefers", ?o)
  ?b BELIEF (?p)
}

FIND(?b) WHERE {
  ?s CONCEPT {name: "Alice"}
  ?o CONCEPT {name: "Quiet"}
  ?p PROPOSITION (?s, "prefers", ?o)
  ?b BELIEF (?p)
} WITH EPISTEMIC {policy: "strict"}

FIND(?b.support.root_groups) WHERE {
  ?s CONCEPT {name: "Dave"}
  ?o CONCEPT {name: "Warm"}
  ?p PROPOSITION (?s, "prefers", ?o)
