}

FIND(?b.support.score) WHERE {
  ?s CONCEPT {name: "Dave"}
  ?o CONCEPT {name: "Warm"}
  ?p PROPOSITION (?s, "prefers", ?o)
  ?b BELIEF (?p)
}

FIND(?b.explanation) WHERE {
  ?s CONCEPT {name: "Dave"}
  ?o CONCEPT {name: "Warm"}
  ?p PROPOSITION (?s, "prefers", ?o)
  ?b BELIEF (?p)
} WITH EPISTEMIC { explanation: "none" }

FIND(?b.status) WHERE {
  ?s CONCEPT {name: "Dave"}
  ?o CONCEPT {name: "Warm"}
  ?p PROPOSITION (?s, "prefers", ?o)
  ?b BELIEF (?p)
} WITH EPISTEMIC { curiosity: 0.5 }

FIND(?s.name, ?slot.status) WHERE {
  ?s CONCEPT {type: "Person", name: "Alice"}
  ?slot BELIEF SLOT (?s, "prefers")
}

FIND(?n, ?slot.status) WHERE {
  ?c CONCEPT {type: "Person", name: ?n}
  FILTER(?n == "Carol")
  ?slot BELIEF SLOT (?n, "prefers")
}
